'use client';

import { signupAdmin } from '@/actions/auth';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useState } from 'react';
import { Loader2, ShieldAlert } from 'lucide-react';
import Link from 'next/link';

export default function SignupPage() {
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (formData: FormData) => {
    setLoading(true);
    setError(null);
    
    // Server Action
    const result = await signupAdmin(formData);
    
    if (result?.error) {
      setError(result.error);
      setLoading(false);
    }
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-100 dark:bg-gray-900">
      <div className="w-full max-w-md space-y-8 rounded-lg border bg-white p-8 shadow-lg dark:border-gray-800 dark:bg-gray-950">
        <div className="text-center">
            <div className="flex justify-center mb-4">
                <ShieldAlert className="h-12 w-12 text-red-600" />
            </div>
          <h1 className="text-3xl font-bold tracking-tight text-gray-900 dark:text-gray-100">
            Super Admin Access
          </h1>
          <p className="mt-2 text-sm text-red-500 font-medium bg-red-50 p-2 rounded border border-red-100 dark:bg-red-900/20 dark:border-red-900/50">
            ⚠ TEMPORARY SIGNUP PAGE ⚠ <br/>
            Creates a user with 'super_admin' role.
          </p>
        </div>

        <form action={handleSubmit} className="mt-8 space-y-6">
          <div className="space-y-4">
            <div>
              <Label htmlFor="fullName">Full Name</Label>
              <Input
                id="fullName"
                name="fullName"
                type="text"
                required
                placeholder="Systems Administrator"
                className="mt-1"
              />
            </div>
            <div>
              <Label htmlFor="email">Email address</Label>
              <Input
                id="email"
                name="email"
                type="email"
                autoComplete="email"
                required
                placeholder="admin@sline.com"
                className="mt-1"
              />
            </div>
            <div>
              <Label htmlFor="password">Password</Label>
              <Input
                id="password"
                name="password"
                type="password"
                autoComplete="new-password"
                required
                className="mt-1"
              />
            </div>
          </div>

          {error && (
            <div className="text-sm font-medium text-red-500 text-center">
              {error}
            </div>
          )}

          <Button type="submit" className="w-full bg-red-600 hover:bg-red-700 text-white" disabled={loading}>
            {loading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Creating Super Admin...
              </>
            ) : (
              'Create Super Admin'
            )}
          </Button>
          
          <div className="text-center text-sm">
            <Link href="/login" className="text-blue-600 hover:underline">
                Back to Login
            </Link>
          </div>
        </form>
      </div>
    </div>
  );
}
