'use server';

import { redirect } from 'next/navigation';

import { cookies } from 'next/headers';
import { createServerClient } from '@supabase/ssr';

// We need a way to create a client that sets cookies for the browser session.
// The existing @/lib/supabase/admin.ts is for ADMIN role and doesn't handle user session cookies the same way 
// (or rather, it uses the Service ID, which we don't want for the session itself initially, 
// strictly speaking we log in as a user).
// However, since this is an Admin App, maybe we just want to verify credentials.
// Standard Supabase Auth flow:

const ADMIN_PREFIX = "admin.";

/**
 * Adds an isolation prefix to the email to separate Admin Dashboard accounts
 * from the main App users in the same Supabase project.
 */
function toAdminAuthEmail(email: string): string {
  // If we wanted to support legacy accounts without prefix, we'd need complex logic.
  // For now, we enforce isolation for all dashboard access.
  return `${ADMIN_PREFIX}${email}`;
}

async function createAuthClient() {
  const cookieStore = await cookies();

  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            );
          } catch {
            // The `setAll` method was called from a Server Component.
          }
        },
      },
    }
  );
}

export async function login(formData: FormData) {
  const email = formData.get('email') as string;
  const password = formData.get('password') as string;
  
  if (!email || !password) {
    return { error: 'Email and password are required' };
  }

  const supabase = await createAuthClient();

  const { error } = await supabase.auth.signInWithPassword({
    email,
    password,
  });

  if (error) {
    return { error: error.message };
  }

  redirect('/dashboard');
}

export async function signupAdmin(formData: FormData) {
  const email = formData.get('email') as string;
  const password = formData.get('password') as string;
  const fullName = formData.get('fullName') as string;

  if (!email || !password || !fullName) {
    return { error: 'All fields are required' };
  }

  const supabase = await createAuthClient();

  // 1. Sign up the user in Supabase Auth
  const { data: authData, error: authError } = await supabase.auth.signUp({
    email,
    password,
    options: {
      data: {
        full_name: fullName,
        role: 'admin', // Metadata role
      },
    },
  });

  if (authError) {
    return { error: authError.message };
  }

  if (!authData.user) {
    return { error: 'Failed to create user' };
  }

  // 2. Add to admin_users table (Bypass RLS using Service Role if needed, but here we try public access first or assume trigger)
  // Actually, since we are not using a trigger, we need to insert it.
  // BUT the user is not logged in as admin yet, so RLS might block if "insert" is restricted.
  // WE MUST USE THE ADMIN CLIENT HERE to bypass RLS for the `admin_users` table insert.
  
  const { createAdminClient } = await import('@/lib/supabase/admin');
  const adminSupabase = createAdminClient();

  const { error: dbError } = await adminSupabase
    .from('admin_users')
    .insert({
      id: authData.user.id,
      email: email,
      role: 'super_admin',
    });

  if (dbError) {
    // Rollback? Or just warn. If auth user exists but admin_user fails, they can't log in.
    return { error: `User created but failed to set Admin role: ${dbError.message}` };
  }

  redirect('/dashboard');
}

export async function logout() {
  const supabase = await createAuthClient();
  await supabase.auth.signOut();
  redirect('/login');
}
